/* Public news only: never reads holdings, cost basis, quantities or broker credentials. */
(() => {
  'use strict';
  const catalog=window.StillNewsSources;
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let generation=0, controller;
  const state={config:null,feed:null,results:null,query:'',provider:'searxng',period:'week',source:'all',error:'',busy:false,offline:false};
  const safeUrl=value=>{try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&(!u.port||u.port==='443')&&catalog.searchDomains.some(d=>u.hostname===d||u.hostname.endsWith('.'+d))?u.href:null;}catch{return null;}};
  const date=value=>{const d=new Date(value);return value&&!Number.isNaN(d.getTime())?new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(d):'Publication date unavailable';};
  const link=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}<span class="sr-only"> (opens in a new tab)</span></a>`;
  const webQuery=()=>`(${state.query.trim()||'financial markets'}) (earnings OR stock OR markets OR economy OR investing) (${catalog.searchDomains.map(d=>'site:'+d).join(' OR ')})`;
  function searchLinks(){return`<div class="news-external"><span>Or search directly:</span>${link('https://search.brave.com/search?'+new URLSearchParams({q:webQuery()}),'Brave')}${link('https://www.google.com/search?'+new URLSearchParams({q:webQuery(),tbm:'nws'}),'Google News')}</div><p class="news-help">Opens the search provider with your query and approved domains. Provider filtering can vary.</p>`;}
  function articles(items){const safe=items.filter(i=>safeUrl(i.url));return safe.length?`<ol class="news-list">${safe.map(i=>`<li><div class="news-meta"><span>${esc(i.source)}</span><span>${esc(i.category)}</span><time ${i.publishedAt?'datetime="'+esc(i.publishedAt)+'"':''}>${esc(date(i.publishedAt))}</time></div><h2>${link(safeUrl(i.url),i.title)}</h2><span class="news-domain">${esc(new URL(i.url).hostname)} ↗</span></li>`).join('')}</ol>`:'<div class="news-empty"><h2>No matching headlines</h2><p>Try another topic or source. No stories have been invented to fill this view.</p></div>';}
  function sources(){return`<section class="news-source-list"><h2>Primary-source feeds</h2><p>Free public releases, with the original publisher, publication time and a link. These cover policy, regulation and economic data rather than a complete market newswire.</p>${catalog.feeds.map(s=>`<article><div><h3>${link(s.homepage,s.name)}</h3><p>${esc(s.category)}</p></div>${link(s.documentation,'Feed documentation')}</article>`).join('')}<h2 class="news-sources-heading">Search providers</h2>${catalog.providers.map(p=>`<article><div><h3>${link(p.url,p.name)}</h3><p>${esc(p.note)}</p></div><span class="news-provider-state">${state.config?.providers.find(v=>v.id===p.id)?.configured?'Configured':'Not configured'}</span></article>`).join('')}<details class="news-domain-list"><summary>Approved search domains (${catalog.searchDomains.length})</summary><p>${catalog.searchDomains.map(esc).join(' · ')}</p></details><p class="news-help">Reviewed ${esc(catalog.reviewedOn)}. Domain approval limits where results come from; it does not verify an article’s claims. Publisher paywalls and usage terms still apply. No full articles are copied.</p></section>`;}
  function feed(){if(state.busy&&!state.feed)return'<p class="news-loading" role="status">Fetching primary-source releases…</p>';if(!state.feed)return`<div class="news-empty"><h2>${state.offline?'Live feeds need the Still server':'Feeds unavailable'}</h2><p>${state.offline?'This hosted preview has no news backend. Run the standalone app with python serve.py to enable feeds and configured search providers.':'The sources could not be loaded. Try again or open an original feed below.'}</p><button class="button" data-news-retry>Try again</button></div><div class="news-feed-links">${catalog.feeds.map(s=>link(s.homepage,s.name)).join('')}</div>`;
    const statuses=state.feed.sources||[],items=state.feed.items.filter(i=>state.source==='all'||i.source===state.source);
    return`<div class="news-feed-toolbar"><label>Source<select id="news-source"><option value="all">All sources</option>${catalog.feeds.map(s=>`<option ${state.source===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><button class="button" data-news-retry ${state.busy?'disabled':''}>Refresh feeds</button></div><div class="news-source-status">${statuses.map(s=>`<span>${esc(s.name)} · ${s.status==='ok'?'Retrieved':s.status==='stale'?'Cached · refresh failed':'Unavailable'}${s.fetchedAt?' '+esc(date(s.fetchedAt)):''}</span>`).join('')}</div>${statuses.some(s=>s.status==='stale')?'<p class="news-help">Some headlines are from an older cached retrieval. Check publication dates and the original source.</p>':''}${items.length?articles(items):`<div class="news-empty"><h2>${statuses.every(s=>s.status==='unavailable')?'Sources could not be reached':'No releases in this view'}</h2><p>Refresh later or check the original sources. Feeds are cached for 10 minutes.</p></div><div class="news-feed-links">${catalog.feeds.map(s=>link(s.homepage,s.name)).join('')}</div>`}<p class="news-help">Checked ${esc(date(state.feed.checkedAt))}. Retrieval time is separate from publication time. Refresh respects the server’s 10-minute cache.</p>`;}
  function search(){const providers=state.config?.providers||catalog.providers.map(p=>({...p,configured:false}));return`<form id="finance-search" class="finance-search"><label class="news-query-label" for="news-query">Search finance sources</label><div class="news-query-row"><input id="news-query" name="query" type="search" maxlength="160" placeholder="Company, ticker, earnings, interest rates…" value="${esc(state.query)}" required minlength="2" autocomplete="off"><button class="button" type="submit" ${state.busy?'disabled':''}>${state.busy?'Searching…':'Search'}</button></div><div class="news-search-options"><label>Provider<select id="news-provider">${providers.map(p=>`<option value="${p.id}" ${state.provider===p.id?'selected':''}>${esc(p.name)}${p.configured?'':' · Not configured'}</option>`).join('')}</select></label><label>Range<select id="news-period">${[['day','Past day'],['week','Past week'],['month','Past month']].map(([key,label])=>`<option value="${key}" ${state.period===key?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="news-help">Only your submitted query is sent to the selected provider. Holdings, quantities, purchase prices and IBKR credentials are never attached. Results are restricted to approved domains; unknown publication dates stay marked.</p></form>${state.error?`<p class="news-error" role="alert">${esc(state.error)}</p>`:''}${!providers.some(p=>p.configured)?'<p class="news-setup-note">In-app search needs a provider on the standalone server: self-hosted SearXNG, a Brave key or a Tavily key. Direct search links below work without an API key.</p>':''}<div id="news-search-links">${searchLinks()}</div>${state.results?`<div class="section-header news-result-heading"><h2>Results for “${esc(state.results.query)}”</h2><span class="small muted">${esc(state.results.provider)} · ${state.results.cached?'Cached':'Retrieved'} ${esc(date(state.results.retrievedAt))}</span></div>${articles(state.results.items)}`:''}`;}
  async function api(path,options={}){const r=await fetch(path,{...options,signal:controller.signal,credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json','X-Still-Request':'1',...(options.headers||{})}});const content=r.headers.get('content-type')||'';if(!content.includes('application/json'))throw new Error('News backend unavailable.');const data=await r.json();if(!r.ok)throw new Error(typeof data.error==='string'?data.error:'News backend unavailable.');return data;}
  async function mount(root,{mode='feed',company=''}={}){
    const version=++generation;controller?.abort();controller=new AbortController();
    if(company&&state.query!==company){state.query=company;state.results=null;state.error='';}
    const render=()=>{if(version!==generation||!root.isConnected)return;root.innerHTML=mode==='sources'?sources():mode==='search'?search():feed();};
    const load=async()=>{state.busy=true;state.error='';render();const jobs=[api('/api/news/config').then(v=>{if(version!==generation)return;state.config=v;state.offline=false;if(!v.providers.find(p=>p.id===state.provider)?.configured){const p=v.providers.find(p=>p.configured);if(p)state.provider=p.id;}})];if(mode==='feed')jobs.push(api('/api/news/feed').then(v=>{if(version===generation)state.feed=v;}));const results=await Promise.allSettled(jobs);if(version!==generation)return;state.offline=results[0].status==='rejected';state.busy=false;render();};
    root.onclick=e=>{if(e.target.closest('[data-news-retry]'))load();};
    root.oninput=e=>{if(e.target.id==='news-query'){state.query=e.target.value;root.querySelector('#news-search-links').innerHTML=searchLinks();}};
    root.onchange=e=>{if(e.target.id==='news-source'){state.source=e.target.value;render();}if(e.target.id==='news-provider')state.provider=e.target.value;if(e.target.id==='news-period')state.period=e.target.value;};
    root.onsubmit=async e=>{if(e.target.id!=='finance-search')return;e.preventDefault();state.query=root.querySelector('#news-query').value;state.provider=root.querySelector('#news-provider').value;state.period=root.querySelector('#news-period').value;state.error='';state.results=null;
      if(!state.config?.providers.find(p=>p.id===state.provider)?.configured){state.error='This provider is not configured. Use a direct search link or configure it on the standalone server.';render();return;}
      state.busy=true;render();try{const result=await api('/api/news/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:state.query,provider:state.provider,period:state.period})});if(version===generation)state.results=result;}catch(error){if(version===generation)state.error=error.name==='AbortError'?'Search cancelled.':error.message;}finally{if(version===generation){state.busy=false;render();}}};
    render();await load();
  }
  window.StillNews={mount,unmount(){generation++;controller?.abort();state.busy=false;}};
})();
